#!/usr/bin/env node
/**
 * import-db.js
 *
 * Imports the SQL dumps generated by export-db.js into fresh databases.
 * Run from the project root AFTER setting up the new machine:
 *
 *   node scripts/import-db.js
 *
 * The databases are created automatically if they don't exist yet.
 * The import uses INSERT OR IGNORE so it's safe to run multiple times.
 *
 * To also import audit_log rows (skipped by default on export), re-export with:
 *   node scripts/export-db.js --with-audit
 * then run this script again.
 */

const { DatabaseSync } = require('node:sqlite');
const fs = require('fs');
const path = require('path');

const EXPORTS_DIR = path.join(__dirname, 'exports');

const IMPORTS = [
  {
    label: 'MCP Virtual Server',
    dbPath: path.join(__dirname, '../mcp-virtual-server/data/virtual-server.db'),
    sqlFile: path.join(EXPORTS_DIR, 'virtual-server.sql'),
  },
  {
    label: 'Banking App',
    dbPath: path.join(__dirname, '../banking-app/backend/banking.db'),
    sqlFile: path.join(EXPORTS_DIR, 'banking.sql'),
  },
];

for (const { label, dbPath, sqlFile } of IMPORTS) {
  if (!fs.existsSync(sqlFile)) {
    console.warn(`⚠️  Skipping "${label}" — export file not found:\n   ${sqlFile}`);
    console.warn(`   Run "node scripts/export-db.js" on the source machine first.\n`);
    continue;
  }

  console.log(`\n📥 Importing: ${label}`);
  console.log(`   SQL:  ${sqlFile}`);
  console.log(`   Into: ${dbPath}`);

  // Ensure parent directory exists
  fs.mkdirSync(path.dirname(dbPath), { recursive: true });

  const db = new DatabaseSync(dbPath);
  const sql = fs.readFileSync(sqlFile, 'utf8');

  try {
    db.exec(sql);
    console.log(`   ✅ Done`);
  } catch (err) {
    console.error(`   ❌ Error importing ${label}: ${err.message}`);
    console.error(`      If the schema hasn't been created yet, start each app once first`);
    console.error(`      so the CREATE TABLE statements run, then re-run this script.`);
    process.exit(1);
  }
}

console.log(`\n✅ Import complete.\n`);
